class Command(BaseCommand):
    help = 'Инициализация данных сайта'

    def handle(self, *args, **kwargs):
        self.stdout.write('Создаём достижения...')
        for ach_data in ACHIEVEMENTS_DATA:
            Achievement.objects.get_or_create(
                title=ach_data['title'],
                defaults=ach_data
            )

        self.stdout.write('Создаём игры...')
        for game_data in GAMES_DATA:
            questions = game_data.pop('questions', [])
            game, created = Game.objects.get_or_create(
                title=game_data['title'],
                defaults=game_data
            )
            if created:
                for i, q in enumerate(questions):
                    q['order'] = i + 1
                    Question.objects.create(game=game, **q)

        self.stdout.write('Создаём курсы...')
        for course_data in COURSES_DATA:
            lessons = course_data.pop('lessons', [])
            course, created = Course.objects.get_or_create(
                title=course_data['title'],
                defaults=course_data
            )
            if created:
                for lesson_data in lessons:
                    Lesson.objects.create(course=course, **lesson_data)

        self.stdout.write(self.style.SUCCESS('✅ Данные успешно загружены!'))
